// ListExpiringArtifacts runs the :many query against postgresql.
func (q *postgresqlQueries) ListExpiringArtifacts(ctx context.Context, db DBTX, arg ListExpiringArtifactsParams) ([]ListExpiringArtifactsRow, error) {
	rows, err := db.QueryContext(ctx, q.listExpiringArtifacts,
		arg.Status,
		arg.ExpiresBefore,
		arg.ResultLimit,
	)
	if err != nil {
		return nil, err
	}

	defer func() { _ = rows.Close() }()

	var items []ListExpiringArtifactsRow

	for rows.Next() {
		var i ListExpiringArtifactsRow

		if err := rows.Scan(
			&i.ID,
			&i.RequestType,
			&i.Status,
			&i.OperationID,
			&i.SubjectID,
			&i.SubjectType,
			&i.SubjectScope,
			&i.CreatedAt,
			&i.LastUpdatedAt,
			&i.ArchivedAt,
			&i.DueAt,
			&i.ExpiresAt,
			&i.CompletedAt,
			&i.ArtifactRef,
			&i.ArtifactBytes,
			&i.DeletedRows,
			&i.AnonymizedRows,
			&i.Failures,
			&i.Retained,
			&i.LastError,
			&i.KeyShreddedAt,
		); err != nil {
			return nil, err
		}

		items = append(items, i)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return items, nil
}

